/**
 * @param {number} zero
 * @param {number} one
 * @param {number} limit
 * @return {number}
 */
var numberOfStableArrays = function(zero, one, limit) {
    let res = 0;

    const dfs = (z, o, cur) => {
        if (z === 0 && o === 0) {
            res++;
            return;
        }

        if (z > 0 && (cur.length < limit || cur.slice(-limit).includes('1'))) {
            dfs(z - 1, o, cur + '0');
        }
        if (o > 0 && (cur.length < limit || cur.slice(-limit).includes('0'))) {
            dfs(z, o - 1, cur + '1');
        }
    };
    dfs(zero, one, '');

    return res;
};

/**
 * @param {number} zero
 * @param {number} one
 * @param {number} limit
 * @return {number}
 */
var numberOfStableArrays = function (zero, one, limit) {
    const MOD = 1000000007;
    const dp = Array.from({ length: zero + 1 }, () =>
        Array.from({ length: one + 1 }, () => [0, 0]),
    );

    for (let i = 0; i <= Math.min(zero, limit); i++) {
        dp[i][0][0] = 1;
    }
    for (let j = 0; j <= Math.min(one, limit); j++) {
        dp[0][j][1] = 1;
    }

    for (let i = 1; i <= zero; i++) {
        for (let j = 1; j <= one; j++) {
            if (i > limit) {
                dp[i][j][0] =
                    dp[i - 1][j][0] + dp[i - 1][j][1] - dp[i - limit - 1][j][1];
            } else {
                dp[i][j][0] = dp[i - 1][j][0] + dp[i - 1][j][1];
            }
            dp[i][j][0] = ((dp[i][j][0] % MOD) + MOD) % MOD;
            if (j > limit) {
                dp[i][j][1] =
                    dp[i][j - 1][1] + dp[i][j - 1][0] - dp[i][j - limit - 1][0];
            } else {
                dp[i][j][1] = dp[i][j - 1][1] + dp[i][j - 1][0];
            }
            dp[i][j][1] = ((dp[i][j][1] % MOD) + MOD) % MOD;
        }
    }
    return (dp[zero][one][0] + dp[zero][one][1]) % MOD;
};
